            }
            $params = $node->getParams();
            $line = isset($params[$position]) ? $params[$position]->getStartLine() : $node->getStartLine();
            $errors[] = $this->errorBuilder->build($this->typeInspector->describe($type), 'parameter $' . $parameter->getName(), $symbol, $line);
