@@ -5,6 +5,8 @@ declare(strict_types=1);
 namespace Tests\Unit\SqlFaker\Grammar;

 use Faker\Factory;
+use InvalidArgumentException;
+use LogicException;
 use PHPUnit\Framework\Attributes\CoversClass;
