            }
        };

        self::assertSame(
            'FROM',
            (new RandomStringGenerator($faker))->lexicalSequence(
                ['SELECT_SYM' => ['SELECT'], 'FROM_SYM' => ['FROM']],
                1,
                1,
            ),
        );
    }

